public static void main(String[] args) throws IOException {
	Reader reader = new Reader();

	final int N = reader.readInt();
	int[] Q = new int[N];
	int[] A = new int[N];
	int[] B = new int[N];

	for (int i = 0; i < N; i++) {
		Q[i] = reader.readInt();
	}

	int n_max = Integer.MAX_VALUE;
	for (int i = 0; i < N; i++) {
		A[i] = reader.readInt();
		if (A[i] != 0) {
			int n = (int) (Q[i] / A[i]);
			if (n_max > n) {
				n_max = n;
			}
		}
	}

	for (int i = 0; i < N; i++) {
		B[i] = reader.readInt();
	}

	reader.close();

	int total_max = 0;
	for (int n = 0; n <= n_max; n++) {
		int m_max = Integer.MAX_VALUE;
		for (int i = 0; i < N; i++) {
			if (B[i] != 0) {
				int m = (Q[i] - A[i] * n) / B[i];
				if (m < m_max) {
					m_max = m;
				}
			}
		}
		if (total_max < n + m_max) {
			total_max = n + m_max;
		}
	}

	System.out.println(total_max);
}

